import * as C from './core.js';
import {SharedStore} from './api.js';
import {parseGroupWorkbook,previewGroupImport,applyGroupImport} from './group-import.js';
import {downloadExcel,downloadTeamCSV} from './export.js';
const $=s=>document.querySelector(s),store=new SharedStore();
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=x=>x==null?'—':Number(x).toLocaleString('ja-JP');
const DT=s=>s?new Date(s).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo'}):'—';
let state=null,revision=0,updatedAt='',season='s5',page='dashboard',detailId='',demo=false,busy=false,dirty=false;
let groupImportPreview=null,groupImportFile='',importData=null,importRows=[],logs=[],logsLoaded=false,query='',teamFilter='',sortKey='name',roleFilter='all',groupFilter='',checkFilter='',checkStatus='incomplete',reviewFilter='pending',reviewQuery='',listPage=0,pendingSave=null;
const pageNames={dashboard:'一門のようす',members:'メンバー名簿',import:'週次CSV取込',teams:'隊と編成',review:'移行・照合確認',audit:'変更履歴',settings:'保存と設定'};
const fieldNames={name:'ゲーム内名前',discordName:'Discord名前',discordId:'Discord ID',originContext:'元所属・経緯（原文）',origin:'元所属',joinHistory:'加入経緯',note:'メモ',role:'役割',teamHistory:'隊履歴',nameHistory:'名前履歴',memberships:'シーズン所属',checks:'運営チェック',memberId:'紐付け先',snapshots:'週次CSV',legacy:'過去実績',formations:'隊編成',meta:'全体設定',seasons:'シーズン',aliases:'別名',issues:'要確認',sources:'元資料',contributions:'貢献履歴'};
const fmtDiff=x=>x==null?'（なし）':typeof x==='object'?JSON.stringify(x,null,2):String(x);
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.classList.toggle('error',error);el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',error?14000:5000);}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'||data instanceof Uint8Array?data:JSON.stringify(data,null,2)],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),15000);}
function options(items,value){return items.map(([v,label])=>`<option value="${E(v)}" ${v===value?'selected':''}>${E(label)}</option>`).join('');}
function memberOptions(value=''){return options([['','既存メンバーを選択'],...Object.values(state.members).sort((a,b)=>a.name.localeCompare(b.name,'ja')).map(m=>[m.id,m.name+' · '+m.id.slice(0,6)])],value);}
function seasonOptions(){return options(Object.values(state.seasons).map(x=>[x.id,x.name]),season);}
function button(text,action,extra='',klass=''){return `<button class="${klass}" data-action="${action}" ${extra}>${E(text)}</button>`;}
function notice(text,kind=''){return `<div class="notice ${kind}">${E(text)}</div>`;}
function stat(label,value,sub){return `<div class="card"><div class="label">${E(label)}</div><div class="number">${E(value)}</div><small>${E(sub)}</small></div>`;}
function header(title,sub,actions=''){return `<div class="heading"><div><div class="eyebrow">HEKIRYU GEKKYO / ${E(state.seasons[season]?.name)}</div><h1>${E(title)}</h1><p class="subline">${E(sub)}</p></div><div class="actions">${actions}</div></div>`;}
function chart(points,label,color='#397f75'){const vals=points.filter(p=>p.value!=null);if(!vals.length)return `<div class="empty">${E(label)}の記録がまだありません。</div>`;
 const w=640,h=220,left=64,right=18,top=16,bottom=40,max=Math.max(...vals.map(p=>p.value),1);const x=i=>points.length===1?(w+left-right)/2:left+i*(w-left-right)/(points.length-1),y=v=>h-bottom-v/max*(h-top-bottom);let lines='';
 for(let i=0;i<=3;i++){const v=max*i/3,yy=y(v);lines+=`<line class="grid" x1="${left}" y1="${yy}" x2="${w-right}" y2="${yy}"/><text x="${left-10}" y="${yy+4}" text-anchor="end">${E(v>=10000?(v/10000).toFixed(v>=100000?0:1)+'万':Math.round(v))}</text>`;}
 let d='',open=false;points.forEach((p,i)=>{if(p.value==null){open=false;return;}d+=(open?' L':' M')+x(i)+','+y(p.value);open=true;});
 const labels=points.map((p,i)=>i===0||i===points.length-1||i%Math.max(1,Math.ceil(points.length/5))===0?`<text x="${x(i)}" y="${h-12}" text-anchor="middle">${E(p.date.slice(5))}</text>`:'').join('');
 return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${E(label)}">${lines}<path d="${d}" fill="none" stroke="${color}" stroke-width="2.5"/>${points.map((p,i)=>p.value==null?'':`<circle cx="${x(i)}" cy="${y(p.value)}" r="4" fill="${color}"><title>${E(p.date)} : ${N(p.value)}</title></circle>`).join('')}${labels}</svg><p class="unitnote">${E(label)} · 欠測値は線をつなぎません。数値は下の表で確認できます。</p>`;}
function sumMetric(rows,key){const present=rows.filter(r=>r[key]!=null);return present.length?present.reduce((a,r)=>a+r[key],0):null;}
function operator(){return sessionStorage.getItem('clan-ledger-operator')||'';}
function modalForm(title,body,submit='保存する'){return new Promise(resolve=>{const d=$('#modal');d.innerHTML=`<form id="modal-form"><h2>${E(title)}</h2>${body}<div class="actions"><button type="button" id="modal-cancel">キャンセル</button><button class="primary" type="submit">${E(submit)}</button></div></form>`;
 const finish=value=>{d.close();d.oncancel=null;resolve(value);};d.oncancel=e=>{e.preventDefault();finish(null);};$('#modal-cancel').onclick=()=>finish(null);$('#modal-form').onsubmit=e=>{e.preventDefault();finish(Object.fromEntries(new FormData(e.target)));};d.showModal();});}
async function ensureOperator(){if(operator())return operator();const data=await modalForm('操作者名を入力',`<p class="subline">変更履歴に残る表示名です。「お菊」「○△」など、わかる名前を入力してください。</p><label>操作者名<input name="operator" required maxlength="80" autocomplete="off" autofocus></label>`,'この名前で操作');if(!data)return null;const name=data.operator.trim();if(!name)throw new Error('操作者名を入力してください');if(!demo)await store.changeOperator(name);else sessionStorage.setItem('clan-ledger-operator',name);return name;}
async function save(next,kind,summary,imported=[]){if(demo)throw new Error('読取プレビューです。共有DBへログインして編集してください');if(busy)return false;C.validateState(next);const op=await ensureOperator();if(!op)return false;busy=true;document.body.classList.add('busy');
 const signature=JSON.stringify([next,revision,op,kind,summary,imported]);if(!pendingSave||pendingSave.signature!==signature)pendingSave={signature,id:C.uid()};
 try{const res=await store.save(next,revision,op,kind,summary,imported,pendingSave.id);state=C.validateState(res.state);revision=res.revision;updatedAt=res.updatedAt;pendingSave=null;dirty=false;logsLoaded=false;toast('共有DBへ保存しました');return true;}
 catch(e){toast(e.message,true);return false;}finally{busy=false;document.body.classList.remove('busy');}}
async function refresh(manual=false){if(demo)return;if(dirty||importRows.length){if(!manual)return;if(!confirm('編集中の入力・CSV照合を閉じ、共有DBの最新データを読み直しますか？'))return;}const res=await store.load();const first=!state;if(first||res.revision!==revision||manual){state=C.validateState(res.state);revision=res.revision;updatedAt=res.updatedAt;dirty=false;logsLoaded=false;if(manual){importRows=[];importData=null;groupImportPreview=null;}if(first||!state.seasons[season])season=state.meta.activeSeasonId;render();}if(manual)toast('最新データを読み込みました');}
function loginView(error=''){const configured=store.config.url&&store.config.key;$('#app').innerHTML=`<main class="login"><div class="eyebrow">MEMBERS & WEEKLY RECORDS</div><h1 class="title">一門手帳</h1><p class="subline">碧龍月梟のメンバーと、積み重なる記録。</p><div class="panel" style="margin-top:24px">${error?notice(error,'error'):''}${!configured?notice(store.configError||'セットアップ担当者がconfig.jsへ接続先を設定してから公開してください。手順はREADMEにあります。','error'):''}<form id="login-form" class="fields"><label>一門共通の合言葉<input name="passphrase" type="password" autocomplete="off" required maxlength="256" aria-describedby="phrase-help"></label><p class="unitnote" id="phrase-help">幹部内で共有された合言葉を入力してください。</p><label>今回の操作者名<input name="operator" autocomplete="off" required maxlength="80" placeholder="お菊、○△、□□…"></label><p class="unitnote">変更履歴に残る自己申告の名前です。正式なゲーム内名と同じでなくても構いません。</p><button class="primary" type="submit" ${!configured?'disabled':''}>共有DBにログイン</button></form></div><div class="panel"><h3>導入前に名簿を確認</h3><p class="subline">初期データやバックアップを選ぶと、読取専用で画面を確認できます。共有DBには保存されません。</p><label style="margin-top:15px">JSONファイルを選択<input id="preview-file" type="file" accept=".json"></label></div><footer>v${C.VERSION} · 操作者名と利用セッションはこのタブで保持（最長12時間）<br>人物データの正本は共有DBです。</footer></main>`;}
async function reconnect(){if(demo)return;const d=await modalForm('再ログイン',`<p class="subline">入力中の内容を保ったまま接続し直します。接続後、保存操作を再度行ってください。</p><div class="fields"><label>一門共通の合言葉<input name="passphrase" type="password" autocomplete="off" maxlength="256" required></label><label>今回の操作者名<input name="operator" value="${E(operator())}" maxlength="80" required></label></div>`,'接続する');if(!d)return;try{await store.login(d.passphrase,d.operator);toast('接続しました。保存・再読込などの操作を再度行ってください。');document.querySelectorAll('[data-action="operator"]').forEach(b=>b.textContent='操作者：'+operator());}finally{d.passphrase='';$('#modal').innerHTML='';}}

function render(){if(!state){loginView();return;}$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">一門手帳<small>碧龍月梟 · OPERATIONS</small></div><nav class="nav" aria-label="メインメニュー"><div class="nav-caption">一門の情報</div>${['dashboard','members','teams'].map(key=>button(pageNames[key],'nav',`data-page="${key}"`,page===key?'active':'')).join('')}<div class="nav-divider"></div><div class="nav-caption">管理・記録</div>${['import','review','audit','settings'].map(key=>button(pageNames[key],'nav',`data-page="${key}"`,page===key?'active':'')).join('')}</nav><div class="sidefoot"><span>記録をつなぎ、人を知る。</span><small>v${C.VERSION} / ${demo?'読取プレビュー':'共有データ'}</small>${button('ログアウト','logout')}</div></aside><div class="workspace"><header class="topbar"><div class="row"><select id="season-select" aria-label="表示シーズン">${seasonOptions()}</select><span class="status">${demo?'読取プレビュー・保存なし':`共有DB · 更新 ${E(DT(updatedAt))} · v${revision}`}</span></div><div class="actions">${button('操作者：'+(operator()||'未設定'),'operator')}${!demo?button('再ログイン','reconnect'):''}${button('再読込','refresh')}${button(demo?'プレビュー終了':'ログアウト','logout')}</div></header><main class="main">${demo?notice('読取専用のプレビューです。この画面のデータは共有DBに保存されていません。'):''}${pageContent()}</main></div></div>`;
 if(page==='members'&&!detailId)renderMemberRows();if(page==='review')renderReviewRows();if(page==='import'&&importRows.length)renderImportRows();if(page==='audit'&&!logsLoaded)loadLogs();}
function pageContent(){if(page==='dashboard')return dashboard();if(page==='members')return detailId?detail():membersView();if(page==='import')return importView();if(page==='teams')return teamsView();if(page==='review')return reviewView();if(page==='audit')return auditView();return settingsView();}
function dashboard(){const ms=membersInSeason(),snaps=C.orderedSnapshots(state,season),last=snaps.at(-1),rows=last?.rows||[],unlinked=Object.values(state.legacy).filter(r=>!r.memberId),groups=new Map();
 for(const r of rows){const team=C.teamAt(state.members[r.memberId],season,last.date)||'未設定';if(!groups.has(team))groups.set(team,[]);groups.get(team).push(r);}
 return header('一門のようす',last?`最新の記録：${last.date} · ${rows.length}名分`:'週次CSVを登録すると、このシーズンの推移が表示されます。',button('週次CSVを取り込む','nav','data-page="import"','primary'))+
 `<div class="cards">${stat('名簿登録',ms.length+' 名',state.seasons[season].name)}${stat('今週戦功 合計',N(sumMetric(rows,'meritWeek')),last?.date||'記録なし')}${stat('今週活躍度 合計',N(sumMetric(rows,'activityWeek')),last?.date||'記録なし')}${stat('蓄積した週次記録',snaps.length+' 週','同じ週は1件として管理')}</div>`+
 (!Object.keys(state.members).length?notice('まだ名簿が登録されていません。「保存と設定」から private/initial-data.json を初期登録してください。'):'')+
 `<div class="split"><section class="panel"><h2>一門の戦功推移</h2>${chart(snaps.slice(-12).map(x=>({date:x.date,value:sumMetric(x.rows,'meritWeek')})),'今週戦功の合計')}<p class="unitnote">各週のCSVに含まれる人数で集計します。構成人数が変わると合計にも影響します。</p></section><section class="panel"><h2>隊別の今週戦功</h2>${rows.length?`<div class="tablewrap"><table><thead><tr><th>取得日時点の隊</th><th>記録人数</th><th>戦功合計</th></tr></thead><tbody>${[...groups].sort().map(([t,rs])=>`<tr><td>${E(t)}</td><td>${rs.length} 名</td><td class="numeric">${N(sumMetric(rs,'meritWeek'))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">週次記録を登録すると集計します。</div>'}</section></div>`+
 `<section class="panel"><h2>確認しておきたい記録</h2><div class="row"><span>未紐付けの元資料：${new Set(unlinked.map(r=>r.sourceName)).size} 名前 / ${unlinked.length} 件</span>${button('移行・照合を開く','nav','data-page="review"')}</div><p class="subline">改名や表記違いは運営者が確認して紐付けます。活動の増減だけで人物を評価しません。</p></section>`+
 (snaps.length?`<section class="panel"><h2>週次記録一覧</h2>${snapshotTable(snaps)}</section>`:'');}
function membersInSeason(){return C.membersIn(state,season);}
function membersView(){const checks=C.checksFor(state,season);return header('メンバー名簿','役職・隊・グループ・シーズン進捗で絞り込めます。',button('メンバーを追加','add-member','','primary'))+`<div class="filters extended-filters"><input id="member-search" placeholder="名前、旧名、Discord、元所属…" aria-label="人物検索" value="${E(query)}"><select id="team-filter">${options([['','すべての隊'],...C.teamDefs(state,season).map(t=>[t.id,t.name]),['__none','隊未設定']],teamFilter)}</select><select id="role-filter">${options([['all','全員'],['officers','幹部（本部＋幹部）'],['general','一般のみ']],roleFilter)}</select><select id="group-filter">${options([['','すべてのグループ'],...groupNames().map(x=>[x,x]),['__none','グループ未設定']],groupFilter)}</select><select id="check-filter">${options([['','進捗項目：すべて'],...checks.map(x=>[x.id,x.name])],checkFilter)}</select><select id="check-status">${options([['incomplete','未完了'],['complete','完了'],['none','未入力']],checkStatus)}</select><select id="member-sort">${options([['name','役職順・名前順'],['meritWeek','役職順・今週戦功'],['meritTotal','役職順・総戦功'],['delta','役職順・前週差'],['activityWeek','役職順・活躍度']],sortKey)}</select></div><p class="subline" id="member-count" style="margin-bottom:12px"></p><div class="tablewrap"><table><thead><tr><th>ゲーム内名前 / Discord</th><th>一門役職</th><th>現在の隊 / 隊役職</th><th>グループ</th><th>今週戦功</th><th>総戦功</th><th>前週戦功</th><th>前週差</th><th>今週活躍度</th><th>所属地方</th></tr></thead><tbody id="member-rows"></tbody></table></div><div class="pagination" id="member-pagination"></div><p class="unitnote">全員表示は本部 → 幹部 → 一般、隊で絞り込むと隊長 → 副隊長 → 一般を優先します。</p>`;}
function groupNames(){return [...new Set([...(state.groupNames||[]),...Object.values(state.members).map(m=>m.group).filter(Boolean)])].sort((a,b)=>a.localeCompare(b,'ja'));}
function teamNames(){return C.teamDefs(state,season).map(t=>t.name);}
function currentTeam(m){return C.teamId(state,season,C.teamAt(m,season));}
function renderMemberRows(){let list=membersInSeason().map(m=>({m,v:C.metrics(state,m.id,season),team:currentTeam(m)}));const q=query.trim().toLocaleLowerCase();list=list.filter(({m,team})=>(!q||[m.name,m.discordName,m.discordId,m.originContext,m.origin,m.note,...m.nameHistory.map(x=>x.name),...Object.values(state.aliases).filter(a=>a.memberId===m.id).map(a=>a.name)].join(' ').toLocaleLowerCase().includes(q))&&(!teamFilter||(teamFilter==='__none'?!team:team===teamFilter))&&(roleFilter==='all'||(roleFilter==='officers'?C.memberRank(m)<2:C.memberRank(m)===2))&&(!groupFilter||(groupFilter==='__none'?!m.group:m.group===groupFilter))&&(!checkFilter||(checkStatus==='none'?(m.checks?.[season]?.[checkFilter]===undefined||m.checks?.[season]?.[checkFilter]===''):C.checkCompleted(m.checks?.[season]?.[checkFilter])===(checkStatus==='complete'))));
 list.sort((a,b)=>C.rosterRank(a.m,b.m,season,Boolean(teamFilter&&teamFilter!=='__none'))||(sortKey==='name'?a.m.name.localeCompare(b.m.name,'ja'):(sortKey==='delta'?(b.v.delta??-Infinity)-(a.v.delta??-Infinity):(b.v.current?.[sortKey]??-Infinity)-(a.v.current?.[sortKey]??-Infinity))||a.m.name.localeCompare(b.m.name,'ja')));
 const pages=Math.max(1,Math.ceil(list.length/50));listPage=Math.max(0,Math.min(listPage,pages-1));$('#member-count').textContent=`${list.length} 名を表示 · ${C.orderedSnapshots(state,season).at(-1)?.date||'週次記録なし'}`;
 $('#member-rows').innerHTML=list.slice(listPage*50,listPage*50+50).map(({m,v,team})=>`<tr><td>${button(m.name,'detail',`data-id="${m.id}"`,'link')}<br><small>${E(m.discordName||'—')}</small></td><td>${E(m.leadership||'一般')}</td><td><span class="tag">${E(C.teamLabel(state,season,team))}</span><br><small>${E(m.teamPositions?.[season]||'一般')}</small></td><td>${E(m.group||'—')}</td><td class="numeric">${N(v.current?.meritWeek)}</td><td class="numeric">${N(v.current?.meritTotal)}</td><td class="numeric">${N(v.previous?.meritWeek)}</td><td class="numeric ${v.delta<0?'negative':''}">${v.delta>0?'+':''}${N(v.delta)}</td><td class="numeric">${N(v.current?.activityWeek)}</td><td>${E(v.current?.region||'—')}</td></tr>`).join('')||'<tr><td colspan="10">該当する人物はいません。</td></tr>';
 $('#member-pagination').innerHTML=button('前へ','member-prev',listPage===0?'disabled':'')+`<span>${listPage+1} / ${pages}</span>`+button('次へ','member-next',listPage>=pages-1?'disabled':'');}
function memberForm(m){const check=m.checks?.[season]||{},defs=C.checksFor(state,season);return `<form id="member-form" class="formgrid" data-id="${m.id}">${[['name','ゲーム内名前'],['discordName','Discord名前'],['discordId','Discord ID（原文）'],['role','役割（原文）'],['origin','元所属'],['joinHistory','加入経緯']].map(([k,l])=>`<label>${l}<input name="${k}" value="${E(m[k])}" ${k==='name'?'required':''} maxlength="500"></label>`).join('')}<label>一門内役職<select name="leadership">${options([['一般','一般'],['幹部','幹部'],['本部','本部']],m.leadership||'一般')}</select></label><div class="full unitnote">所属グループ：${E(m.group||'未設定')}（変更は「保存と設定」からExcel一括インポート）</div><label class="full">ざっくり元所属とか経緯（原文）<textarea name="originContext">${E(m.originContext)}</textarea></label><label class="full">自由記述メモ<textarea name="note">${E(m.note)}</textarea></label><div class="full"><h3>シーズン進捗 · ${E(state.seasons[season].name)}</h3><p class="unitnote">項目は「隊と編成」から追加・変更できます。未入力／完了／対象外を選べます。</p></div>${defs.map(x=>`<label>${E(x.name)}<select name="check_${E(x.id)}">${options([['','未入力'],['○','完了'],['対象外','対象外']],C.checkCompleted(check[x.id])?'○':check[x.id]==='対象外'?'対象外':'')}</select></label>`).join('')}<label>現在の隊<select name="team">${options([['','未設定'],...C.teamDefs(state,season).map(t=>[t.id,t.name])],currentTeam(m))}</select></label><label>隊内役職<select name="teamPosition">${options([['一般','一般'],['副隊長','副隊長'],['隊長','隊長']],m.teamPositions?.[season]||'一般')}</select></label><label>変更日<input name="date" type="date" required value="${C.today()}"></label><label>所属状態<select name="status">${options(['在籍','休止','離脱','過去在籍'].map(x=>[x,x]),m.memberships.filter(x=>x.seasonId===season).at(-1)?.status||'在籍')}</select></label><label>編成メモ<input name="teamNote" placeholder="隊を変更する理由など"></label><div class="full actions"><button type="submit" class="primary" ${demo?'disabled':''}>変更を共有DBへ保存</button><span class="muted">CSV取込では、この入力欄は上書きされません。</span></div></form>`;}
