function snapshotTable(xs){return `<div class="tablewrap"><table><thead><tr><th>取得日</th><th>人数</th><th>戦功今週 合計</th><th>活躍度今週 合計</th><th>元ファイル</th><th>訂正履歴</th><th></th></tr></thead><tbody>${[...xs].reverse().map(x=>`<tr><td>${E(x.date)}</td><td>${x.rows.length}</td><td class="numeric">${N(sumMetric(x.rows,'meritWeek'))}</td><td class="numeric">${N(sumMetric(x.rows,'activityWeek'))}</td><td>${E(x.fileName)}</td><td>${x.versions.length} 回</td><td>${button('内容','snapshot',`data-id="${x.id}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
