function renderReviewRows(){const data=Object.values(state.legacy).filter(r=>(reviewFilter==='all'||!r.memberId)&&r.sourceName.toLowerCase().includes(reviewQuery.toLowerCase())),groups=new Map();for(const r of data){if(!groups.has(r.sourceName))groups.set(r.sourceName,[]);groups.get(r.sourceName).push(r);}$('#review-rows').innerHTML=`<p class="subline">${groups.size} 名前 / ${data.length} 件</p>`+[...groups].map(([name,rs])=>`<details class="details"><summary>${E(name)} <span class="tag ${rs.some(r=>!r.memberId)?'warn':''}">${rs.some(r=>!r.memberId)?'未紐付け':E(state.members[rs[0].memberId]?.name)}</span> <small>${rs.length} 件</small></summary><div class="tablewrap"><table><thead><tr><th>シート / 行</th><th>区分</th><th>元の値</th><th>紐付け先</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td>${E(r.sheet)} / ${r.row}</td><td>${E(r.group)}</td><td class="wrap">${E(Object.entries(r.values).map(([k,v])=>k+'：'+v).join(' / '))}</td><td>${E(state.members[r.memberId]?.name||'未紐付け')}</td><td>${button('この記録を紐付け','review-record',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div>${button('この名前の未紐付け記録をまとめて紐付け','review-name',`data-name="${E(name)}"`)}</details>`).join('')||'<div class="empty">該当する資料はありません。</div>';}
